/** Decode one MirVerified. */
export function decodeMirVerified(reader: BinaryReader): MirVerified {
    const retention = decodeRetentionTable(reader);

    return {
        retention,
    };
}

/** Return one JSON value for one MirVerified. */
export function toJsonMirVerified(value: MirVerified): Json {
    return {
        retention: toJsonRetentionTable(value.retention),
    };
}

/** Return one MirVerified from one JSON value. */
export function fromJsonMirVerified(value: Json): MirVerified {
    const object = jsonObject(value);

    return {
        retention: fromJsonRetentionTable(jsonField(object, "retention")),
    };
}

/** Whole-program analysis columns shared across the optimization of every module. */
export type ProgramAnalysis = {
    /** Every defined symbol in the program. */
    readonly symbols: ReadonlyArray<Symbol>;
    /** Whether each symbol is reachable from a program root. */
    readonly live: BitSet;
    /** Program-wide incoming reference count of each symbol. */
    readonly references: ReadonlyArray<number>;
    /** Whether each symbol's address is taken anywhere in the program. */
    readonly addressTaken: BitSet;
    /** Whether each symbol is internal to the program. */
    readonly internal: BitSet;
    /** Strongly connected components of the whole-program call graph. */
    readonly components: CallComponentTable;
    /** Function effects and escape paths with reusable recursive components. */
    readonly effects: ProgramEffectTable;
};

export const ProgramAnalysis = {
    /** Encode this value. */
    encode(writer: BinaryWriter, value: ProgramAnalysis): void {
        encodeProgramAnalysis(writer, value);
    },

    /** Decode one ProgramAnalysis. */
    decode(reader: BinaryReader): ProgramAnalysis {
        return decodeProgramAnalysis(reader);
    },

    /** Return this value as JSON. */
    toJson(value: ProgramAnalysis): Json {
        return toJsonProgramAnalysis(value);
    },

    /** Return one ProgramAnalysis from one JSON value. */
    fromJson(value: Json): ProgramAnalysis {
        return fromJsonProgramAnalysis(value);
    },
};

/** Encode one ProgramAnalysis. */
export function encodeProgramAnalysis(writer: BinaryWriter, value: ProgramAnalysis): void {
    writer.writeUnsigned(value.symbols.length);
    for (const item0 of value.symbols) {
        encodeSymbol(writer, item0);
    }
    encodeBitSet(writer, value.live);
    writer.writeUnsigned(value.references.length);
    for (const item2 of value.references) {
        writer.writeUnsigned(item2);
    }
    encodeBitSet(writer, value.addressTaken);
    encodeBitSet(writer, value.internal);
    encodeCallComponentTable(writer, value.components);
    encodeProgramEffectTable(writer, value.effects);
}

/** Decode one ProgramAnalysis. */
export function decodeProgramAnalysis(reader: BinaryReader): ProgramAnalysis {
    const symbols = (() => {
        const length0 = reader.readNumber();
        const items0: Array<Symbol> = [];
        for (let index = 0; index < length0; index += 1) {
            items0.push(decodeSymbol(reader));
        }
        return items0;
    })();
    const live = decodeBitSet(reader);
    const references = (() => {
        const length2 = reader.readNumber();
        const items2: Array<number> = [];
        for (let index = 0; index < length2; index += 1) {
            items2.push(reader.readNumber());
        }
        return items2;
    })();
    const addressTaken = decodeBitSet(reader);
    const internal = decodeBitSet(reader);
    const components = decodeCallComponentTable(reader);
    const effects = decodeProgramEffectTable(reader);

    return {
        symbols,
        live,
        references,
        addressTaken,
        internal,
        components,
        effects,
    };
}

/** Return one JSON value for one ProgramAnalysis. */
export function toJsonProgramAnalysis(value: ProgramAnalysis): Json {
    return {
        symbols: value.symbols.map((item0) => toJsonSymbol(item0)),
        live: toJsonBitSet(value.live),
        references: value.references.map((item0) => item0),
        addressTaken: toJsonBitSet(value.addressTaken),
        internal: toJsonBitSet(value.internal),
        components: toJsonCallComponentTable(value.components),
        effects: toJsonProgramEffectTable(value.effects),
    };
}

/** Return one ProgramAnalysis from one JSON value. */
export function fromJsonProgramAnalysis(value: Json): ProgramAnalysis {
    const object = jsonObject(value);

    return {
        symbols: jsonArray(jsonField(object, "symbols")).map((item0) => fromJsonSymbol(item0)),
        live: fromJsonBitSet(jsonField(object, "live")),
        references: jsonArray(jsonField(object, "references")).map((item0) => jsonInteger(item0)),
        addressTaken: fromJsonBitSet(jsonField(object, "addressTaken")),
        internal: fromJsonBitSet(jsonField(object, "internal")),
        components: fromJsonCallComponentTable(jsonField(object, "components")),
        effects: fromJsonProgramEffectTable(jsonField(object, "effects")),
    };
}
